/* ShiftWise Design System */
@import url('https://fonts.googleapis.com/css2?family=Karla:wght@300;400;500;600;700&family=Playfair+Display+SC:wght@400;700&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --primary: #0051C3;
  --primary-dark: #0041A3;
  --accent: #DE5052;
  --white: #FFFFFF;
  --bg: #F8FAFC;
  --text: #1E293B;
  --text-light: #64748B;
  --border: #E2E8F0;
  --success: #10B981;
  --font-heading: 'Playfair Display SC', serif;
  --font-body: 'Karla', sans-serif;
  --max-w: 1200px;
  --shadow: 0 4px 6px -1px rgba(0,0,0,0.1);
  --radius: 8px;
  --transition: 150ms ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* Typography */
h1, h2, h3, h4 { font-family: var(--font-heading); font-weight: 700; line-height: 1.2; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.5rem); }
p { max-width: 65ch; }

/* Container */
.container { max-width: var(--max-w); margin: 0 auto; padding: 0 24px; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 14px 28px; border-radius: var(--radius); font-weight: 600; font-size: 1rem;
  transition: all var(--transition);
}
.btn-primary { background: var(--primary); color: var(--white); }
.btn-primary:hover { background: var(--primary-dark); transform: translateY(-2px); }
.btn-accent { background: var(--accent); color: var(--white); }
.btn-accent:hover { opacity: 0.9; transform: translateY(-2px); }
.btn-outline { border: 2px solid var(--primary); color: var(--primary); }
.btn-outline:hover { background: var(--primary); color: var(--white); }

/* Header */
.header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: var(--white); border-bottom: 1px solid var(--border);
  padding: 16px 0;
}
.header .container { display: flex; align-items: center; justify-content: space-between; }
.logo { font-family: var(--font-heading); font-size: 1.5rem; font-weight: 700; color: var(--primary); }
.nav { display: flex; align-items: center; gap: 32px; }
.nav-links { display: flex; gap: 32px; list-style: none; }
.nav-links a { font-weight: 500; transition: color var(--transition); }
.nav-links a:hover, .nav-links a.active { color: var(--primary); }
.nav-cta .btn { padding: 10px 20px; }

/* Hamburger */
.hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 8px; }
.hamburger span { width: 24px; height: 2px; background: var(--text); transition: all var(--transition); }
.hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.hamburger.active span:nth-child(2) { opacity: 0; }
.hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile Nav */
.mobile-nav {
  position: fixed; top: 65px; left: 0; right: 0; bottom: 0;
  background: var(--white); z-index: 999; padding: 24px;
  transform: translateX(100%); transition: transform 0.3s ease;
}
.mobile-nav.active { transform: translateX(0); }
.mobile-nav ul { list-style: none; display: flex; flex-direction: column; gap: 16px; }
.mobile-nav a { font-size: 1.25rem; font-weight: 500; display: block; padding: 12px 0; }

/* Hero */
.hero {
  padding: 140px 0 80px; text-align: center;
  background: linear-gradient(135deg, var(--bg) 0%, var(--white) 100%);
}
.hero h1 { color: var(--text); margin-bottom: 24px; }
.hero p { font-size: 1.25rem; color: var(--text-light); margin: 0 auto 40px; }
.hero-btns { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }

/* Section */
.section { padding: 80px 0; }
.section-alt { background: var(--bg); }
.section-header { text-align: center; margin-bottom: 60px; }
.section-header h2 { margin-bottom: 16px; }
.section-header p { color: var(--text-light); margin: 0 auto; }

/* Features Grid */
.features-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 32px; }
.feature-card {
  padding: 32px; border-radius: var(--radius); background: var(--white);
  border: 1px solid var(--border); transition: all var(--transition);
}
.feature-card:hover { border-color: var(--primary); transform: translateY(-4px); }
.feature-icon { width: 56px; height: 56px; background: var(--primary); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; margin-bottom: 20px; }
.feature-icon svg { width: 28px; height: 28px; stroke: var(--white); fill: none; stroke-width: 2; }
.feature-card h3 { margin-bottom: 12px; }
.feature-card p { color: var(--text-light); font-size: 0.95rem; }

/* How It Works */
.steps { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 40px; }
.step { text-align: center; }
.step-num {
  width: 48px; height: 48px; background: var(--accent); color: var(--white);
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; font-weight: 700; margin: 0 auto 16px;
}
.step h3 { margin-bottom: 8px; }
.step p { color: var(--text-light); font-size: 0.95rem; }

/* Testimonials */
.testimonial-carousel { position: relative; max-width: 800px; margin: 0 auto; }
.testimonial-track { overflow: hidden; }
.testimonial-slides { display: flex; transition: transform 0.4s ease; }
.testimonial-slide { min-width: 100%; padding: 0 20px; }
.testimonial-card {
  background: var(--white); border-radius: var(--radius); padding: 40px;
  border: 1px solid var(--border); text-align: center;
}
.testimonial-card blockquote { font-size: 1.25rem; font-style: italic; margin-bottom: 24px; line-height: 1.8; }
.testimonial-card cite { font-style: normal; font-weight: 600; color: var(--primary); }
.testimonial-card cite span { display: block; font-weight: 400; color: var(--text-light); font-size: 0.9rem; }
.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; background: var(--white); border: 1px solid var(--border);
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  cursor: pointer; transition: all var(--transition);
}
.carousel-arrow:hover { background: var(--primary); color: var(--white); border-color: var(--primary); }
.carousel-arrow svg { width: 20px; height: 20px; stroke: currentColor; fill: none; stroke-width: 2; }
.carousel-prev { left: -22px; }
.carousel-next { right: -22px; }
.carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 24px; }
.carousel-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--border); cursor: pointer; transition: all var(--transition); }
.carousel-dot.active { background: var(--primary); }

/* Stats */
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; text-align: center; }
.stat-value { font-family: var(--font-heading); font-size: clamp(2rem, 4vw, 3rem); font-weight: 700; color: var(--primary); }
.stat-label { color: var(--text-light); margin-top: 8px; }

/* Pricing */
.pricing-toggle { display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 48px; }
.toggle-switch {
  width: 56px; height: 30px; background: var(--border); border-radius: 15px;
  position: relative; cursor: pointer; transition: background var(--transition);
}
.toggle-switch.active { background: var(--primary); }
.toggle-switch::after {
  content: ''; position: absolute; width: 24px; height: 24px; background: var(--white);
  border-radius: 50%; top: 3px; left: 3px; transition: transform var(--transition);
}
.toggle-switch.active::after { transform: translateX(26px); }
.pricing-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 32px; max-width: 1000px; margin: 0 auto; }
.pricing-card {
  background: var(--white); border: 2px solid var(--border); border-radius: var(--radius);
  padding: 40px; text-align: center; transition: all var(--transition);
}
.pricing-card.featured { border-color: var(--primary); position: relative; }
.pricing-card.featured::before {
  content: 'Most Popular'; position: absolute; top: -12px; left: 50%; transform: translateX(-50%);
  background: var(--accent); color: var(--white); padding: 4px 16px; border-radius: 12px; font-size: 0.85rem; font-weight: 600;
}
.pricing-card h3 { font-size: 1.5rem; margin-bottom: 8px; }
.pricing-card .price { font-size: 2.5rem; font-weight: 700; color: var(--primary); margin: 16px 0; }
.pricing-card .price span { font-size: 1rem; font-weight: 400; color: var(--text-light); }
.pricing-card ul { list-style: none; text-align: left; margin: 24px 0; }
.pricing-card li { padding: 10px 0; border-bottom: 1px solid var(--border); display: flex; align-items: center; gap: 12px; }
.pricing-card li::before { content: '✓'; color: var(--success); font-weight: 700; }
.pricing-card li.missing::before { content: '—'; color: var(--text-light); }
.pricing-card li.missing { color: var(--text-light); }

/* FAQ */
.faq-item { border-bottom: 1px solid var(--border); }
.faq-question {
  width: 100%; padding: 24px 0; display: flex; justify-content: space-between; align-items: center;
  font-size: 1.1rem; font-weight: 600; cursor: pointer; text-align: left;
}
.faq-question svg { width: 24px; height: 24px; stroke: currentColor; transition: transform var(--transition); }
.faq-item.active .faq-question svg { transform: rotate(180deg); }
.faq-answer {
  max-height: 0; overflow: hidden; transition: max-height 0.3s ease, padding 0.3s ease;
}
.faq-item.active .faq-answer { max-height: 200px; padding-bottom: 24px; }
.faq-answer p { color: var(--text-light); }

/* Team */
.team-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 32px; }
.team-card { text-align: center; }
.team-avatar {
  width: 120px; height: 120px; background: var(--primary); border-radius: 50%; margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center; color: var(--white); font-size: 2.5rem; font-weight: 700;
}
.team-card h4 { margin-bottom: 4px; }
.team-card p { color: var(--text-light); font-size: 0.9rem; }

/* Contact */
.contact-form { max-width: 600px; margin: 0 auto; }
.form-group { margin-bottom: 24px; }
.form-group label { display: block; font-weight: 500; margin-bottom: 8px; }
.form-group label span { color: var(--accent); }
.form-group input, .form-group select, .form-group textarea {
  width: 100%; padding: 14px 16px; border: 1px solid var(--border); border-radius: var(--radius);
  font-size: 1rem; font-family: inherit; transition: border-color var(--transition);
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus { outline: none; border-color: var(--primary); }
.form-group input.error, .form-group select.error, .form-group textarea.error { border-color: var(--accent); }
.form-group .error-msg { color: var(--accent); font-size: 0.85rem; margin-top: 6px; display: none; }
.form-group.has-error .error-msg { display: block; }
.form-group textarea { min-height: 120px; resize: vertical; }
.form-success {
  background: var(--success); color: var(--white); padding: 20px; border-radius: var(--radius);
  text-align: center; display: none;
}
.form-success.active { display: block; }
.form-success h3 { margin-bottom: 8px; }

/* Locations */
.locations { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 32px; text-align: center; }
.location-card h4 { color: var(--primary); margin-bottom: 8px; }
.location-card p { color: var(--text-light); font-size: 0.9rem; }

/* CTA Section */
.cta-section {
  background: var(--primary); color: var(--white); text-align: center; padding: 80px 0;
}
.cta-section h2 { color: var(--white); margin-bottom: 16px; }
.cta-section p { margin: 0 auto 32px; opacity: 0.9; }
.cta-section .btn-accent { background: var(--white); color: var(--primary); }
.cta-section .btn-accent:hover { background: var(--bg); }

/* Footer */
.footer { background: var(--text); color: var(--white); padding: 60px 0 24px; }
.footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px; margin-bottom: 48px; }
.footer-brand .logo { color: var(--white); margin-bottom: 16px; }
.footer-brand p { color: rgba(255,255,255,0.7); font-size: 0.9rem; max-width: 280px; }
.footer h4 { color: var(--white); margin-bottom: 20px; font-size: 1rem; }
.footer ul { list-style: none; }
.footer ul li { margin-bottom: 12px; }
.footer ul a { color: rgba(255,255,255,0.7); transition: color var(--transition); }
.footer ul a:hover { color: var(--white); }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; text-align: center; color: rgba(255,255,255,0.5); font-size: 0.9rem; }

/* Feature Detail */
.feature-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }
.feature-detail h2 { margin-bottom: 20px; }
.feature-detail p { margin-bottom: 24px; color: var(--text-light); }
.feature-visual { background: var(--bg); border-radius: var(--radius); padding: 40px; min-height: 300px; display: flex; align-items: center; justify-content: center; }
.feature-visual-placeholder { width: 100%; height: 250px; background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%); border-radius: var(--radius); opacity: 0.1; }

/* Integrations */
.integrations-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.integration-card {
  background: var(--white); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 24px; text-align: center; transition: all var(--transition);
}
.integration-card:hover { border-color: var(--primary); transform: translateY(-2px); }
.integration-card h4 { color: var(--primary); margin-bottom: 12px; }
.integration-card p { font-size: 0.85rem; color: var(--text-light); }

/* Responsive */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .feature-detail { grid-template-columns: 1fr; }
  .feature-detail.reverse { direction: ltr; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .hamburger { display: flex; }
  .hero { padding: 120px 0 60px; }
  .stats { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .carousel-arrow { display: none; }
}

@media (max-width: 480px) {
  .hero-btns { flex-direction: column; align-items: center; }
  .pricing-cards { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
}

/* Animations */
@keyframes countUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
.animate-count { animation: countUp 0.6s ease forwards; }

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

