  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  font-size: 1.25rem; font-weight: 700; margin: 0 auto 16px;
}
.step h3 { margin-bottom: 8px; }
.step p { color: var(--text-light); font-size: 0.95rem; }

/* Testimonials */
.testimonial-carousel { position: relative; max-width: 800px; margin: 0 auto; }
.testimonial-track { overflow: hidden; }
.testimonial-slides { display: flex; transition: transform 0.4s ease; }
.testimonial-slide { min-width: 100%; padding: 0 20px; }
.testimonial-card {
  background: var(--white); border-radius: var(--radius); padding: 40px;
  border: 1px solid var(--border); text-align: center;
}
.testimonial-card blockquote { font-size: 1.25rem; font-style: italic; margin-bottom: 24px; line-height: 1.8; }
.testimonial-card cite { font-style: normal; font-weight: 600; color: var(--primary); }
.testimonial-card cite span { display: block; font-weight: 400; color: var(--text-light); font-size: 0.9rem; }
.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; background: var(--white); border: 1px solid var(--border);
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  cursor: pointer; transition: all var(--transition);
}
.carousel-arrow:hover { background: var(--primary); color: var(--white); border-color: var(--primary); }
.carousel-arrow svg { width: 20px; height: 20px; stroke: currentColor; fill: none; stroke-width: 2; }
.carousel-prev { left: -22px; }
.carousel-next { right: -22px; }
.carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 24px; }
.carousel-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--border); cursor: pointer; transition: all var(--transition); }
.carousel-dot.active { background: var(--primary); }

/* Stats */
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; text-align: center; }
.stat-value { font-family: var(--font-heading); font-size: clamp(2rem, 4vw, 3rem); font-weight: 700; color: var(--primary); }
.stat-label { color: var(--text-light); margin-top: 8px; }

/* Pricing */
.pricing-toggle { display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 48px; }
.toggle-switch {
  width: 56px; height: 30px; background: var(--border); border-radius: 15px;
  position: relative; cursor: pointer; transition: background var(--transition);
