.footer h4 { color: var(--white); margin-bottom: 20px; font-size: 1rem; }
.footer ul { list-style: none; }
.footer ul li { margin-bottom: 12px; }
.footer ul a { color: rgba(255,255,255,0.7); transition: color var(--transition); }
.footer ul a:hover { color: var(--white); }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; text-align: center; color: rgba(255,255,255,0.5); font-size: 0.9rem; }

/* Feature Detail */
.feature-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }
.feature-detail.reverse { direction: rtl; }
.feature-detail.reverse > * { direction: ltr; }
.feature-detail h2 { margin-bottom: 20px; }
.feature-detail p { margin-bottom: 24px; color: var(--text-light); }
.feature-visual { background: var(--bg); border-radius: var(--radius); padding: 40px; min-height: 300px; display: flex; align-items: center; justify-content: center; }
